from taf.internal.scf.exceptions import ElementNotFound

from taf.gnb.oam.ne3s.ws.components.connection.messages import (
    NotificationMsg, AttachmentType, NotificationGroup, NotificationType)


class NE3SFeedback(NotificationMsg):
    def __init__(self, *args, **kwargs):
        super(NE3SFeedback, self).__init__(*args, **kwargs)
        self.message_result = self.attachment.message_result
        self.status = self.attachment.status

    def __str__(self):
        return str(self.attachment)

    @staticmethod
    def matches(soap, attachment):
        return isinstance(attachment, AttachmentType.Feedback)


class ProvisionError(NotificationMsg):
    def __init__(self, *args, **kwargs):
        super(ProvisionError, self).__init__(*args, **kwargs)
        mos = self.attachment.managed_objects
        self.status = mos[0].status.value
        self.textual_response = mos[0].textualResponse.value
        self.error_code = mos[0].errorCode.value

    def __str__(self):
        msg = 'Status: {},\ntextual response: {}, \nerror code: {}'
        return msg.format(self.status, self.textual_response, self.error_code)

    @staticmethod
    def matches(soap, attachment):
        return (isinstance(attachment, AttachmentType.Ocos)
                and len(attachment.managed_objects) > 0
                and attachment.has_elements(
                    attachment.managed_objects[0],
                    ['errorCode', 'status', 'textualResponse']))


class ActiveVersion(NotificationMsg):
    def __init__(self, *args, **kwargs):
        super(ActiveVersion, self).__init__(*args, **kwargs)

        self.active_sw_release_ver = None
        self._set_active_version()

    def _set_active_version(self):
        for mo in self.attachment.managed_objects:
            for p in mo:
                try:
                    if p.name == 'activeSWReleaseVersion':
                        self.active_sw_release_ver = p.value.upper()
                        break
                except (AttributeError, ElementNotFound):
                    pass

    @staticmethod
    def matches(soap, attachment):
        return (isinstance(attachment, AttachmentType.Ocos)
                and attachment.get_managed_objects_for_class('mnl'))


class CurrentPlan(NotificationMsg):
    def __init__(self, *args, **kwargs):
        super(CurrentPlan, self).__init__(*args, **kwargs)
        self.current_plan = self.attachment.content

    @classmethod
    def matches(cls, soap, attachment):
        return (isinstance(attachment, AttachmentType.Ocos)
                and isinstance(soap, NotificationType.ReportOperationStatus)
                and len(attachment.managed_objects) > 0)


class CMNotificationGroup(NotificationGroup):
    QUEUE_IDS = ("common_queue", )
    NOTIFICATIONS = (ActiveVersion, NE3SFeedback, ProvisionError, CurrentPlan)
